"use client";

import { useEffect, useRef, type ReactNode } from "react";

type ScrollExperienceProps = {
  children?: ReactNode;
};
function loadScrollLibraries() {
  return Promise.all([
    import("lenis"),
    import("gsap"),
    import("gsap/ScrollTrigger"),
  ]);
}


export function ScrollExperience({ children }: ScrollExperienceProps = {}) {
  const rootRef = useRef<HTMLDivElement>(null);
  const lenisRef = useRef<{ resize: () => void; scrollTo: (target: number, options?: Record<string, unknown>) => void } | null>(null);
  const scrollTriggerRef = useRef<{ update: () => void } | null>(null);

  useEffect(() => {
    let frame = 0;

    const restoreHashTarget = () => {
      window.cancelAnimationFrame(frame);
      frame = window.requestAnimationFrame(() => {
        const currentHash = window.location.hash.slice(1);
        const target = currentHash
          ? document.getElementById(currentHash)
          : null;

        if (target) {
          const lenis = lenisRef.current;
          if (lenis) {
            lenis.resize();
            target.scrollIntoView({ block: "start" });
            lenis.scrollTo(window.scrollY, {
              immediate: true,
              force: true,
            });
            scrollTriggerRef.current?.update();
          } else {
            target.scrollIntoView({ block: "start" });
          }
        }
      });
    };

    window.addEventListener("hashchange", restoreHashTarget);
    restoreHashTarget();

    return () => {
      window.cancelAnimationFrame(frame);
      window.removeEventListener("hashchange", restoreHashTarget);
    };
  }, []);

  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") {
      return;
    }

    const root = rootRef.current || document.getElementById("top") || document.body;
    if (!root) {
      return;
    }
    const reducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)",
    );

    let cleanupExperience = () => {};
    let generation = 0;

    async function createExperience() {
      const currentGeneration = generation;
      const [{ default: Lenis }, { gsap }, { ScrollTrigger }] =
        await loadScrollLibraries();

      if (
        currentGeneration !== generation ||
        reducedMotion.matches ||
        !root
      ) {
        return;
      }

      gsap.registerPlugin(ScrollTrigger);

      const lenis = new Lenis({
        duration: 1.05,
        smoothWheel: true,
        anchors: true,
      });

      const updateScroll = () => ScrollTrigger.update();
      const updateLenis = (time: number) => lenis.raf(time * 1000);

      lenis.on("scroll", updateScroll);
      gsap.ticker.add(updateLenis);
      gsap.ticker.lagSmoothing(0);

      const context = gsap.context(() => {
        gsap
          .timeline({ defaults: { ease: "power3.out" } })
          .from("[data-hero-kicker]", { opacity: 0, y: 18, duration: 0.6 })
          .from(
            "[data-hero-line]",
            { yPercent: 112, duration: 1.05, stagger: 0.1 },
            "-=0.35",
          )
          .from(
            "[data-hero-support]",
            { opacity: 0, y: 24, duration: 0.75, stagger: 0.08 },
            "-=0.5",
          )
          .from(
            "[data-orbit-node]",
            { opacity: 0, scale: 0.65, duration: 0.55, stagger: 0.07 },
            "-=0.55",
          );

        gsap.to("[data-scroll-progress]", {
          scaleX: 1,
          ease: "none",
          scrollTrigger: {
            trigger: root,
            start: "top top",
            end: "bottom bottom",
            scrub: 0.2,
          },
        });


        const desktopEffects = gsap.matchMedia();

        desktopEffects.add("(min-width: 1081px)", () => {
          gsap.to("[data-orbit-ring='outer']", {
            rotate: 28,
            ease: "none",
            scrollTrigger: {
              trigger: "[data-hero]",
              start: "top top",
              end: "bottom top",
              scrub: 1,
            },
          });

          gsap.to("[data-orbit-ring='inner']", {
            rotate: -42,
            ease: "none",
            scrollTrigger: {
              trigger: "[data-hero]",
              start: "top top",
              end: "bottom top",
              scrub: 1,
            },
          });

        });

        const previousCleanup = cleanupExperience;
        cleanupExperience = () => {
          desktopEffects.revert();
          previousCleanup();
        };
      }, root);

      let revealObserver: IntersectionObserver | null = null;
      if (typeof window.IntersectionObserver === "function") {
        revealObserver = new IntersectionObserver(
          (entries) => {
            entries.forEach((entry) => {
              if (entry.isIntersecting) {
                const element = entry.target as HTMLElement;
                gsap.to(element, {
                  opacity: 1,
                  y: 0,
                  duration: 0.85,
                  ease: "power3.out",
                  overwrite: "auto",
                });
                revealObserver?.unobserve(element);
              }
            });
          },
          { rootMargin: "0px 0px -12% 0px" },
        );

        root.querySelectorAll<HTMLElement>("[data-reveal]").forEach((element) => {
          gsap.set(element, { opacity: 0, y: 44 });
          revealObserver?.observe(element);
        });
      }

      lenisRef.current = lenis;
      scrollTriggerRef.current = ScrollTrigger;
      ScrollTrigger.refresh();

      if (window.location.hash) {
        const target = document.getElementById(window.location.hash.slice(1));
        if (target) {
          lenis.resize();
          target.scrollIntoView({ block: "start" });
          lenis.scrollTo(window.scrollY, { immediate: true, force: true });
          ScrollTrigger.update();
        }
      }

      const cleanupHashAndLenis = () => {
        revealObserver?.disconnect();
        lenisRef.current = null;
        scrollTriggerRef.current = null;
        lenis.off("scroll", updateScroll);
        gsap.ticker.remove(updateLenis);
        ScrollTrigger.getAll().forEach((t) => t.kill());
        lenis.destroy();
      };
      const previousCleanup = cleanupExperience;
      cleanupExperience = () => {
        previousCleanup();
        context.revert();
        cleanupHashAndLenis();
      };
    }

    let frameId: number | null = null;

    const stopExperience = () => {
      generation += 1;
      if (frameId !== null) {
        window.cancelAnimationFrame(frameId);
        frameId = null;
      }
      cleanupExperience();
      cleanupExperience = () => {};
    };

    const syncMotionPreference = () => {
      stopExperience();

      if (!reducedMotion.matches) {
        frameId = window.requestAnimationFrame(() => {
          frameId = null;
          void createExperience();
        });
      }
    };

    reducedMotion.addEventListener("change", syncMotionPreference);
    syncMotionPreference();
    return () => {
      reducedMotion.removeEventListener("change", syncMotionPreference);
      stopExperience();
    };
  }, []);

  return children ? <div ref={rootRef}>{children}</div> : null;
}
